'use client';

import type { ReactNode } from 'react';
import { cn } from '../../utils';

export interface EmptyStateProps {
  /** An illustration from `illustrations.tsx`, or any drawn SVG. */
  art?: ReactNode;
  title: string;
  /** One line on why it is empty and what fills it. */
  description?: string;
  /** A single action. Omit when the user cannot do anything about it. */
  action?: ReactNode;
  size?: 'sm' | 'default';
  className?: string;
}

/**
 * The state a trading UI spends most of its life in.
 *
 * Before the open, between sessions, on a fresh account, every list here is
 * empty - so an empty state is not a corner case to apologise for, it is a
 * primary screen. Each one names what is missing and what would fill it,
 * rather than saying "no data".
 */
export function EmptyState({
  art,
  title,
  description,
  action,
  size = 'default',
  className,
}: EmptyStateProps) {
  return (
    <div
      className={cn(
        'flex flex-col items-center justify-center gap-3 text-center',
        size === 'sm' ? 'px-4 py-6' : 'px-6 py-10',
        className,
      )}
    >
      {art && <div className={cn('opacity-90', size === 'sm' && 'scale-75')}>{art}</div>}
      <div className="flex max-w-[34ch] flex-col gap-1">
        <p className="text-foreground text-xs font-semibold tracking-wide">{title}</p>
        {description && (
          <p className="text-muted-foreground text-[11px] leading-relaxed">{description}</p>
        )}
      </div>
      {action}
    </div>
  );
}

'use client';

import type { SVGProps } from 'react';
import { cn } from '../../utils';

/**
 * Empty-state illustrations.
 *
 * One drawn family, not five unrelated pictures: every one is built from the
 * same vocabulary - hairline rules at the same rhythm, a dashed reference
 * line, and small tick marks - so an empty book and an empty blotter read as
 * two states of the same instrument.
 *
 * All strokes are `currentColor` at graded opacity, so the caller sets one
 * colour and the drawing stays in the theme. 1.25px stroke throughout, matching
 * the hairline weight of the components they sit inside.
 */

type IllustrationProps = SVGProps<SVGSVGElement>;

function Frame({ className, children, ...props }: IllustrationProps) {
  return (
    <svg
      viewBox="0 0 120 80"
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={cn('h-20 w-auto text-muted-foreground', className)}
      {...props}
    >
      {children}
    </svg>
  );
}

/** Empty ladder: rows thinning out, with a gap where the touch would be. */
export function EmptyBookArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      {[0, 1, 2].map((i) => (
        <g key={`a${i}`} opacity={0.18 + i * 0.07}>
          <rect
            x={18}
            y={8 + i * 10}
            width={84 - i * 6}
            height={5}
            rx={1.5}
            fill="currentColor"
          />
        </g>
      ))}
      {/* The spread. The one place the drawing breaks rhythm, because that is
          the thing the component is for. */}
      <line
        x1={10}
        y1={43}
        x2={110}
        y2={43}
        stroke="currentColor"
        strokeWidth={1.25}
        strokeDasharray="3 4"
        opacity={0.55}
      />
      {[0, 1, 2].map((i) => (
        <g key={`b${i}`} opacity={0.25 - i * 0.07}>
          <rect
            x={18}
            y={52 + i * 10}
            width={72 + i * 6}
            height={5}
            rx={1.5}
            fill="currentColor"
          />
        </g>
      ))}
    </Frame>
  );
}

/** Empty tape: a paper strip running out, prints trailing to nothing. */
export function EmptyTapeArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      <rect
        x={14}
        y={16}
        width={92}
        height={48}
        rx={3}
        stroke="currentColor"
        strokeWidth={1.25}
        opacity={0.35}
      />
      {[0, 1, 2, 3].map((i) => (
        <g key={i} opacity={0.4 - i * 0.09}>
          <rect x={24} y={26 + i * 10} width={18} height={4} rx={1.5} fill="currentColor" />
          <rect x={50} y={26 + i * 10} width={22} height={4} rx={1.5} fill="currentColor" />
          <rect x={80} y={26 + i * 10} width={14} height={4} rx={1.5} fill="currentColor" />
        </g>
      ))}
      {/* Sprocket perforations, so it reads as tape rather than a table. */}
      {[0, 1, 2, 3, 4].map((i) => (
        <circle key={i} cx={9} cy={22 + i * 9} r={1.4} fill="currentColor" opacity={0.3} />
      ))}
      {[0, 1, 2, 3, 4].map((i) => (
        <circle key={i} cx={111} cy={22 + i * 9} r={1.4} fill="currentColor" opacity={0.3} />
      ))}
    </Frame>
  );
}

/** No positions: a flat book — axis with nothing plotted against it. */
export function EmptyPositionsArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      <line x1={18} y1={14} x2={18} y2={62} stroke="currentColor" strokeWidth={1.25} opacity={0.4} />
      <line x1={18} y1={62} x2={104} y2={62} stroke="currentColor" strokeWidth={1.25} opacity={0.4} />
      {[0, 1, 2].map((i) => (
        <line
          key={i}
          x1={15}
          y1={22 + i * 14}
          x2={18}
          y2={22 + i * 14}
          stroke="currentColor"
          strokeWidth={1.25}
          opacity={0.3}
        />
      ))}
      <line
        x1={18}
        y1={40}
        x2={104}
        y2={40}
        stroke="currentColor"
        strokeWidth={1.25}
        strokeDasharray="3 4"
        opacity={0.5}
      />
      <circle cx={61} cy={40} r={3} stroke="currentColor" strokeWidth={1.25} opacity={0.55} />
    </Frame>
  );
}

/** No orders: a blank ticket, fields unfilled. */
export function EmptyOrdersArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      <path
        d="M30 10h52a3 3 0 0 1 3 3v54a3 3 0 0 1-3 3H30a3 3 0 0 1-3-3V13a3 3 0 0 1 3-3Z"
        stroke="currentColor"
        strokeWidth={1.25}
        opacity={0.35}
      />
      <rect x={36} y={19} width={28} height={4} rx={1.5} fill="currentColor" opacity={0.4} />
      {[0, 1, 2].map((i) => (
        <rect
          key={i}
          x={36}
          y={32 + i * 11}
          width={40 - i * 8}
          height={4}
          rx={1.5}
          fill="currentColor"
          opacity={0.22}
        />
      ))}
      <line
        x1={36}
        y1={60}
        x2={76}
        y2={60}
        stroke="currentColor"
        strokeWidth={1.25}
        strokeDasharray="3 4"
        opacity={0.45}
      />
    </Frame>
  );
}

/** Empty watchlist: rows waiting, each with a flat line where a trend goes. */
export function EmptyWatchlistArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      {[0, 1, 2].map((i) => (
        <g key={i} opacity={0.4 - i * 0.1}>
          <rect x={14} y={18 + i * 16} width={20} height={4} rx={1.5} fill="currentColor" />
          <line
            x1={44}
            y1={20 + i * 16}
            x2={78}
            y2={20 + i * 16}
            stroke="currentColor"
            strokeWidth={1.25}
            strokeDasharray="3 4"
          />
          <rect x={88} y={18 + i * 16} width={18} height={4} rx={1.5} fill="currentColor" />
        </g>
      ))}
    </Frame>
  );
}

/** Nothing to chart: axes with a dashed, featureless series. */
export function EmptyChartArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      <line x1={16} y1={12} x2={16} y2={62} stroke="currentColor" strokeWidth={1.25} opacity={0.4} />
      <line x1={16} y1={62} x2={106} y2={62} stroke="currentColor" strokeWidth={1.25} opacity={0.4} />
      <path
        d="M16 48 L38 38 L58 44 L78 28 L106 34"
        stroke="currentColor"
        strokeWidth={1.25}
        strokeDasharray="3 4"
        opacity={0.45}
      />
      {[0, 1, 2, 3].map((i) => (
        <line
          key={i}
          x1={30 + i * 22}
          y1={62}
          x2={30 + i * 22}
          y2={65}
          stroke="currentColor"
          strokeWidth={1.25}
          opacity={0.3}
        />
      ))}
    </Frame>
  );
}

'use client';

import type { ComponentProps } from 'react';
import { cn } from '../../utils';

/**
 * Loading states.
 *
 * Each skeleton is shaped like the thing it replaces - the ladder skeleton has
 * a spread row, the chart skeleton has an axis and a volume pane - so the
 * layout does not jump when real data lands and the eye already knows where to
 * look. A generic grey box would be cheaper and would cost a reflow every time.
 *
 * The pulse is opacity only, and stops under `prefers-reduced-motion`.
 */
export function Skeleton({ className, ...props }: ComponentProps<'div'>) {
  return (
    <div
      data-slot="skeleton"
      className={cn('bg-muted-foreground/15 animate-shimmer rounded-sm', className)}
      {...props}
    />
  );
}

/** Deterministic widths: random ones would re-roll on every render. */
const LADDER_WIDTHS = [62, 48, 74, 55, 68, 44, 80, 51, 66, 58, 72, 46];

export function OrderBookSkeleton({ depth = 8, className }: { depth?: number; className?: string }) {
  const row = (key: string, i: number, side: 'bid' | 'ask') => (
    <div key={key} className="flex items-center gap-2 px-2.5 py-[5px]">
      <Skeleton
        className={cn('h-2.5 flex-1', side === 'bid' ? 'bg-up/15' : 'bg-down/15')}
        style={{ maxWidth: `${LADDER_WIDTHS[i % LADDER_WIDTHS.length]}%` }}
      />
      <Skeleton className="h-2.5 w-10" />
      <Skeleton className="h-2.5 w-8" />
    </div>
  );

  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-2 border-b px-2.5 py-1.5">
        <Skeleton className="h-2 w-10" />
        <Skeleton className="ml-auto h-2 w-8" />
        <Skeleton className="h-2 w-8" />
      </div>
      {Array.from({ length: depth }, (_, i) => row(`a${i}`, i, 'ask'))}
      <div className="bg-muted my-0.5 flex items-center justify-between border-y px-2.5 py-2">
        <Skeleton className="h-2.5 w-16" />
        <Skeleton className="h-2.5 w-20" />
      </div>
      {Array.from({ length: depth }, (_, i) => row(`b${i}`, i + 3, 'bid'))}
    </div>
  );
}

export function TradeTapeSkeleton({ rows = 10, className }: { rows?: number; className?: string }) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-2 border-b px-2.5 py-1.5">
        <Skeleton className="h-2 w-8" />
        <Skeleton className="ml-auto h-2 w-10" />
        <Skeleton className="h-2 w-8" />
      </div>
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="grid grid-cols-3 gap-2 px-2.5 py-[5px]">
          <Skeleton className="h-2.5 w-12" />
          <Skeleton className="h-2.5 w-12 justify-self-end" />
          <Skeleton className="h-2.5 w-8 justify-self-end" />
        </div>
      ))}
    </div>
  );
}

/** Candle bars at varied heights around a baseline, plus axis and volume. */
const CANDLE_HEIGHTS = [38, 52, 44, 61, 49, 70, 57, 42, 66, 51, 74, 46, 59, 68, 40, 55, 63, 47];

export function CandleChartSkeleton({
  height = 320,
  className,
}: {
  height?: number;
  className?: string;
}) {
  return (
    <div
      className={cn('flex w-full flex-col gap-2 p-2', className)}
      style={{ height }}
      aria-hidden="true"
    >
      <div className="flex min-h-0 flex-1 items-end gap-[3px] pr-14">
        {CANDLE_HEIGHTS.concat(CANDLE_HEIGHTS).map((h, i) => (
          <Skeleton
            key={i}
            className="min-w-[3px] flex-1"
            style={{ height: `${h}%`, animationDelay: `${(i % 12) * 60}ms` }}
          />
        ))}
      </div>
      <div className="flex h-[16%] items-end gap-[3px] pr-14">
        {CANDLE_HEIGHTS.concat(CANDLE_HEIGHTS).map((h, i) => (
          <Skeleton
            key={i}
            className="min-w-[3px] flex-1 opacity-60"
            style={{ height: `${h * 0.7}%`, animationDelay: `${(i % 12) * 60}ms` }}
          />
        ))}
      </div>
      <div className="flex justify-between pr-14">
        {Array.from({ length: 6 }, (_, i) => (
          <Skeleton key={i} className="h-2 w-8" />
        ))}
      </div>
    </div>
  );
}

export function TableSkeleton({
  rows = 4,
  columns = 6,
  className,
}: {
  rows?: number;
  columns?: number;
  className?: string;
}) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-4 border-b px-2.5 py-2">
        {Array.from({ length: columns }, (_, i) => (
          <Skeleton key={i} className={cn('h-2', i === 0 ? 'w-14' : 'flex-1')} />
        ))}
      </div>
      {Array.from({ length: rows }, (_, r) => (
        <div key={r} className="flex gap-4 border-b px-2.5 py-2.5">
          {Array.from({ length: columns }, (_, i) => (
            <Skeleton key={i} className={cn('h-2.5', i === 0 ? 'w-14' : 'flex-1')} />
          ))}
        </div>
      ))}
    </div>
  );
}

export function WatchlistSkeleton({ rows = 6, className }: { rows?: number; className?: string }) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="flex items-center gap-2.5 border-b px-2.5 py-2">
          <Skeleton className="h-2.5 w-12" />
          <Skeleton className="h-4 w-14" />
          <Skeleton className="ml-auto h-2.5 w-12" />
          <Skeleton className="h-2.5 w-10" />
        </div>
      ))}
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';
import { ChevronDownIcon, ChevronUpIcon } from 'lucide-react';
import { formatCompact, formatPrice } from '../../format';
import { useInstrument } from '../../theme/theme-provider';
import type { Instrument, Quote } from '../../types';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '../ui/table';
import { Delta } from './delta';
import { toArray } from '../../utils';
import { EmptyState } from './empty-state';
import { EmptyWatchlistArt } from './illustrations';
import { Price } from './price';
import { Sparkline } from './sparkline';
import { TableSkeleton } from './skeletons';

export type QuoteColumn = 'last' | 'change' | 'bid' | 'ask' | 'spread' | 'high' | 'low' | 'volume' | 'trend';

export interface QuoteGridProps {
  quotes: Quote[];
  instrument?: Partial<Instrument>;
  columns?: QuoteColumn[];
  /** Click a header to sort. */
  sortable?: boolean;
  selected?: string;
  onSelect?: (quote: Quote) => void;
  loading?: boolean;
  className?: string;
}

const HEADERS: Record<QuoteColumn, string> = {
  last: 'Last',
  change: 'Change',
  bid: 'Bid',
  ask: 'Ask',
  spread: 'Spread',
  high: 'High',
  low: 'Low',
  volume: 'Volume',
  trend: 'Trend',
};

type SortKey = QuoteColumn | 'symbol';

/**
 * A dense multi-instrument quote board.
 *
 * Sorting is stable and always descending-first on numeric columns, because
 * the question is nearly always "what moved most", not "what moved least" —
 * one click should answer it rather than two.
 */
export function QuoteGrid({
  quotes,
  instrument,
  columns = ['last', 'change', 'bid', 'ask', 'volume', 'trend'],
  sortable = true,
  selected,
  onSelect,
  loading = false,
  className,
}: QuoteGridProps) {
  const inst = useInstrument(instrument);
  const [sort, setSort] = useState<{ key: SortKey; desc: boolean }>({ key: 'symbol', desc: false });

  const valueFor = (q: Quote, key: SortKey): number | string => {
    switch (key) {
      case 'symbol':
        return q.symbol;
      case 'change':
        return (q.last - q.prevClose) / q.prevClose;
      case 'spread':
        return (q.ask ?? 0) - (q.bid ?? 0);
      case 'trend':
        return q.last;
      default:
        return (q[key as keyof Quote] as number) ?? 0;
    }
  };

  const rows0 = toArray(quotes);

  const rows = useMemo(() => {
    const copy = rows0.slice();
    copy.sort((a, b) => {
      const av = valueFor(a, sort.key);
      const bv = valueFor(b, sort.key);
      const cmp =
        typeof av === 'string' || typeof bv === 'string'
          ? String(av).localeCompare(String(bv))
          : av - bv;
      return sort.desc ? -cmp : cmp;
    });
    return copy;
  }, [rows0, sort]);

  if (loading) return <TableSkeleton rows={6} columns={columns.length + 1} className={className} />;

  if (rows0.length === 0) {
    return (
      <EmptyState
        className={className}
        art={<EmptyWatchlistArt />}
        title="No instruments"
        description="Add symbols to this board and their quotes stream in here."
      />
    );
  }

  const toggle = (key: SortKey) =>
    setSort((prev) =>
      prev.key === key
        ? { key, desc: !prev.desc }
        : { key, desc: key !== 'symbol' },
    );

  const header = (key: SortKey, label: string) => (
    <TableHead key={key}>
      {sortable ? (
        <button
          type="button"
          onClick={() => toggle(key)}
          aria-sort={sort.key === key ? (sort.desc ? 'descending' : 'ascending') : 'none'}
          className="hover:text-foreground inline-flex cursor-pointer items-center gap-1 uppercase"
        >
          {label}
          {sort.key === key &&
            (sort.desc ? (
              <ChevronDownIcon className="size-3" />
            ) : (
              <ChevronUpIcon className="size-3" />
            ))}
        </button>
      ) : (
        label
      )}
    </TableHead>
  );

  return (
    <Table className={className}>
      <TableHeader>
        <TableRow>
          {header('symbol', 'Symbol')}
          {columns.map((c) => header(c, HEADERS[c]))}
        </TableRow>
      </TableHeader>
      <TableBody>
        {rows.map((quote) => {
          const change = quote.last - quote.prevClose;
          return (
            <TableRow
              key={quote.symbol}
              data-state={quote.symbol === selected ? 'selected' : undefined}
              onClick={onSelect ? () => onSelect(quote) : undefined}
              className={onSelect ? 'cursor-pointer' : undefined}
            >
              <TableCell>{quote.symbol}</TableCell>
              {columns.map((column) => (
                <TableCell key={column}>
                  {column === 'last' && (
                    <Price value={quote.last} flash instrument={instrument} />
                  )}
                  {column === 'change' && (
                    <span className="flex justify-end">
                      <Delta
                        value={change}
                        percent={change / quote.prevClose}
                        precision={inst.pricePrecision}
                        icon={false}
                      />
                    </span>
                  )}
                  {column === 'bid' && (
                    <span className="text-up">
                      {quote.bid !== undefined ? formatPrice(quote.bid, inst.pricePrecision) : '--'}
                    </span>
                  )}
                  {column === 'ask' && (
                    <span className="text-down">
                      {quote.ask !== undefined ? formatPrice(quote.ask, inst.pricePrecision) : '--'}
                    </span>
                  )}
                  {column === 'spread' &&
                    (quote.bid !== undefined && quote.ask !== undefined
                      ? formatPrice(quote.ask - quote.bid, inst.pricePrecision)
                      : '--')}
                  {column === 'high' &&
                    (quote.dayHigh !== undefined
                      ? formatPrice(quote.dayHigh, inst.pricePrecision)
                      : '--')}
                  {column === 'low' &&
                    (quote.dayLow !== undefined
                      ? formatPrice(quote.dayLow, inst.pricePrecision)
                      : '--')}
                  {column === 'volume' && formatCompact(quote.volume ?? 0)}
                  {column === 'trend' && (
                    <span className="flex justify-end">
                      <Sparkline
                        data={quote.history ?? []}
                        baseline={quote.prevClose}
                        width={64}
                        height={18}
                      />
                    </span>
                  )}
                </TableCell>
              ))}
            </TableRow>
          );
        })}
      </TableBody>
    </Table>
  );
}

'use client';

import { TrendingDownIcon, TrendingUpIcon } from 'lucide-react';
import { directionOf, formatPercent, formatSigned } from '../../format';
import { cn } from '../../utils';
import { Badge } from '../ui/badge';

export interface DeltaProps {
  /** Absolute change. Omit to show the percentage alone. */
  value?: number;
  /** Change as a ratio (0.0421 renders as +4.21%). */
  percent?: number;
  precision?: number;
  /** Boxed badge instead of bare text. */
  pill?: boolean;
  /** Prefix with a trend icon. */
  icon?: boolean;
  className?: string;
}

/**
 * The change indicator.
 *
 * Direction is carried three ways at once - color, an icon, and an explicit
 * sign. Color alone fails a colorblind reader; in a grayscale screenshot or a
 * printed risk report it fails everyone.
 */
export function Delta({
  value,
  percent,
  precision = 2,
  pill = false,
  icon = true,
  className,
}: DeltaProps) {
  const basis = value ?? percent ?? 0;
  const direction = directionOf(basis);

  const parts: string[] = [];
  if (value !== undefined) parts.push(formatSigned(value, precision));
  if (percent !== undefined) {
    parts.push(
      value !== undefined
        ? `(${formatPercent(percent, precision, false)})`
        : formatPercent(percent, precision),
    );
  }

  const Icon =
    direction === 'up' ? TrendingUpIcon : direction === 'down' ? TrendingDownIcon : null;
  const tone = direction === 'up' ? 'text-up' : direction === 'down' ? 'text-down' : 'text-flat';

  const body = (
    <>
      {icon && Icon && <Icon className="size-3 shrink-0" aria-hidden="true" />}
      <span className="sr-only">
        {direction === 'up' ? 'up' : direction === 'down' ? 'down' : 'unchanged'}{' '}
      </span>
      {parts.join(' ')}
    </>
  );

  if (pill) {
    return (
      <Badge variant={direction} className={cn('font-mono tabular-nums', className)}>
        {body}
      </Badge>
    );
  }

  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 font-mono text-xs font-semibold tabular-nums whitespace-nowrap',
        tone,
        className,
      )}
    >
      {body}
    </span>
  );
}

'use client';

import { useInstrument } from '../../theme/theme-provider';
import type { Instrument } from '../../types';
import { formatPrice } from '../../format';
import { usePriceFlash } from '../../hooks';
import { cn } from '../../utils';

export interface PriceProps {
  value: number;
  instrument?: Partial<Instrument>;
  precision?: number;
  /** Flash the cell green or red for one beat on every change. */
  flash?: boolean;
  /** Color the text by its direction against this reference (e.g. prevClose). */
  colorAgainst?: number;
  /**
   * Render the trailing N digits larger - the "big figure" convention, where
   * the handle stays quiet and the digits that actually move draw the eye.
   */
  emphasizeLast?: number;
  className?: string;
}

/** A price. Monospaced and tabular so a column of them aligns on the decimal. */
export function Price({
  value,
  instrument,
  precision,
  flash = false,
  colorAgainst,
  emphasizeLast = 0,
  className,
}: PriceProps) {
  const inst = useInstrument(instrument);
  const digits = precision ?? inst.pricePrecision;
  const flashDirection = usePriceFlash(flash ? value : 0);
  const text = formatPrice(value, digits);

  const tone =
    colorAgainst === undefined || value === colorAgainst
      ? undefined
      : value > colorAgainst
        ? 'text-up'
        : 'text-down';

  const classes = cn(
    'rounded-sm font-mono tabular-nums',
    tone,
    flash && flashDirection === 'up' && 'animate-flash-up',
    flash && flashDirection === 'down' && 'animate-flash-down',
    className,
  );

  if (emphasizeLast > 0 && emphasizeLast < text.length) {
    const split = text.length - emphasizeLast;
    return (
      <span className={classes}>
        {text.slice(0, split)}
        <span className="text-[1.2em] font-semibold">{text.slice(split)}</span>
      </span>
    );
  }

  return <span className={classes}>{text}</span>;
}

